import java.util.*;

public class Main {
    static final int INF = 0x3f3f3f3f; // large number, used as infinity

    static int n, m, k, c, d;
    static int t, n_, m_; // t = n + k + 1, n_ = n * t + 1, m_ = number of flow edges

    // flow graph arrays
    static int[] uu, vv, uv, cost, cost_; // uv = u ^ v
    static int[] cc; // capacity for each directed arc (2 per edge)
    static int[] head; // adjacency list head (per node)
    static int[] nextArc; // next arc index in adjacency list
    static int arcCount; // number of directed arcs added ( = 2 * m_ )

    // data structures for Dijkstra (successive shortest path)
    static int[] pi, kk, bb; // distance, number of edges, predecessor arc
    static int[] pq, iq; // binary heap and inverse mapping
    static int cnt; // heap size

    // original graph adjacency (undirected edges)
    static ArrayList<Integer>[] adj;

    // binary heap utilities
    static boolean lessThan(int u, int v) {
        return pi[u] < pi[v] || (pi[u] == pi[v] && kk[u] < kk[v]);
    }

    static int i2(int i) {
        int c = i * 2;
        if (c > cnt) return 0;
        if (c < cnt && lessThan(pq[c+1], pq[c])) return c+1;
        return c;
    }

    static void pq_up(int u) {
        int i, j;
        for (i = iq[u]; (j = i / 2) > 0 && lessThan(u, pq[j]); i = j) {
            pq[i] = pq[j];
            iq[pq[j]] = i;
        }
        pq[i] = u;
        iq[u] = i;
    }

    static void pq_dn(int u) {
        int i, j;
        for (i = iq[u]; (j = i2(i)) > 0 && lessThan(pq[j], u); i = j) {
            pq[i] = pq[j];
            iq[pq[j]] = i;
        }
        pq[i] = u;
        iq[u] = i;
    }

    static void pq_add(int u) {
        iq[u] = ++cnt;
        pq_up(u);
    }

    static int pq_remove_first() {
        int u = pq[1];
        int v = pq[cnt--];
        iq[v] = 1;
        pq_dn(v);
        return u;
    }

    // add a directed arc in the flow graph
    static void addArc(int u, int h_) {
        nextArc[arcCount] = head[u];
        head[u] = arcCount;
        // we store the h_ in the adjacency list implicitly via index? No, we need h_ per arc.
        // We'll have a separate array arcs[] to store h_ for each arc index.
        // But we can compute h_ from the arc index: arc index is the position in the adjacency list chain.
        // To keep it simple, we'll store the edge index h_ directly as the arc index.
        // Actually, we will store the arc index as the h_ itself. So we need head[u] to point to an arc index (which equals h_).
        // But we also need a 'next' chain. So we will use an array nextArc where nextArc[h_] points to the next arc index.
        // However, we are adding arcs with specific h_. So we need to set nextArc[h_] = head[u] and head[u] = h_.
        // Then in Dijkstra, we iterate arcs by for (int h_ = head[u]; h_ != -1; h_ = nextArc[h_]).
        // So we need to know the h_ value for each arc. That's exactly the index we pass to addArc.
        // So we can do:
        // nextArc[h_] = head[u]; head[u] = h_;
        // But then arcCount is not needed; we just use the given h_.
        // However, we allocate arrays sized to max number of arcs (2*m_max). So we can set nextArc[h_] accordingly.
        // The addArc method will be called when we also create the edge and assign h_.
        // Let's restructure: In link(), we create a new edge h = m_++. Then we have two arcs: h_ = 2*h and h_ = 2*h+1.
        // We then add each arc by calling addArc(u, h_).
        // So we need head array and nextArc array of size 2*m_max.
        // We'll set nextArc[h_] = head[u]; head[u] = h_;
        // This is straightforward.
        nextArc[h_] = head[u];
        head[u] = h_;
    }

    // add a flow edge with capacity cap and cost cos
    static void link(int u, int v, int cap, int cos) {
        int h = m_++;
        uu[h] = u; vv[h] = v; uv[h] = u ^ v; cost[h] = cos; cost_[h] = cos;
        int fw = 2 * h; // forward arc index
        int bw = 2 * h + 1; // backward arc index
        cc[fw] = cap;
        cc[bw] = 0; // reverse capacity starts 0
        addArc(u, fw);
        addArc(v, bw);
    }

    // Dijkstra's algorithm to find shortest path in residual graph
    static void dijkstra(int s) {
        for (int i = 0; i < n_; i++) {
            pi[i] = INF;
            kk[i] = 0;
            iq[i] = 0; // not in heap
        }
        pi[s] = 0;
        kk[s] = 0;
        cnt = 0;
        pq_add(s);

        while (cnt > 0) {
            int u = pq_remove_first();
            for (int h_ = head[u]; h_ != -1; h_ = nextArc[h_]) {
                if (cc[h_] == 0) continue; // no capacity
                int h = h_ >> 1; // edge index
                int v = (h_ & 1) == 0 ? vv[h] : uu[h]; // other endpoint
                int p = pi[u] + ((h_ & 1) == 0 ? cost_[h] : -cost_[h]);
                if (pi[v] == INF || pi[v] > p || (pi[v] == p && kk[v] > kk[u] + 1)) {
                    pi[v] = p;
                    kk[v] = kk[u] + 1;
                    bb[v] = h_; // predecessor arc
                    if (iq[v] == 0) {
                        pq_add(v);
                    } else {
                        pq_up(v);
                    }
                }
            }
        }
    }

    // push 1 unit of flow along the path found by Dijkstra
    static void push(int s, int t) {
        for (int u = t; u != s; u = u ^ uv[bb[u] >> 1]) {
            int h_ = bb[u];
            cc[h_]--;
            cc[h_ ^ 1]++;
        }
    }

    // min-cost max-flow (successive shortest augmenting path)
    static int edmonds_karp(int s, int t) {
        System.arraycopy(cost, 0, cost_, 0, m_);
        while (true) {
            dijkstra(s);
            if (pi[t] == INF) break;
            push(s, t);
            for (int h = 0; h < m_; h++) {
                int u = uu[h], v = vv[h];
                if (pi[u] != INF && pi[v] != INF) {
                    cost_[h] += pi[u] - pi[v];
                }
            }
        }
        int totalCost = 0;
        for (int h = 0; h < m_; h++) {
            totalCost += cost[h] * cc[2 * h + 1]; // flow on reverse arcs
        }
        return totalCost;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        k = sc.nextInt();
        c = sc.nextInt();
        d = sc.nextInt();

        int[] start = new int[k];
        for (int i = 0; i < k; i++) {
            start[i] = sc.nextInt() - 1;
        }

        // build original graph adjacency
        adj = new ArrayList[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int i = 0; i < m; i++) {
            int a = sc.nextInt() - 1;
            int b = sc.nextInt() - 1;
            adj[a].add(b);
            adj[b].add(a);
        }

        t = n + k + 1;
        n_ = n * t + 1;
        // compute maximum number of flow edges
        int m_max = k + (m * 2 * k + n) * (t - 1);
        // allocate arrays
        uu = new int[m_max];
        vv = new int[m_max];
        uv = new int[m_max];
        cost = new int[m_max];
        cost_ = new int[m_max];
        cc = new int[2 * m_max];
        head = new int[n_];
        nextArc = new int[2 * m_max];
        // initialize head to -1
        Arrays.fill(head, -1);
        // initialize nextArc is not necessary but we will fill with -1 upon adding arcs
        // we'll set nextArc[?] = -1 when head is -1; we set link such that the last arc in chain has nextArc = -1.
        // In addArc, we set nextArc[h_] = head[u]; head[u] = h_; so if head[u] initially -1, then the first arc's next will be -1.
        // So no need to initialize nextArc, but we will ensure that when we later iterate, we stop at -1.

        m_ = 0;
        arcCount = 0; // not used

        // build flow network
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                for (int j : adj[i]) {
                    int v = j * t + s + 1;
                    for (int x = 1; x <= k; x++) {
                        link(u, v, 1, c + (x * 2 - 1) * d);
                    }
                }
            }
        }
        for (int i = 0; i < n; i++) {
            for (int s = 0; s < t - 1; s++) {
                int u = i * t + s;
                int v = u + 1;
                link(u, v, k, i == 0 ? 0 : c);
            }
        }
        for (int h = 0; h < k; h++) {
            link(n_ - 1, start[h] * t, 1, 0);
        }

        // allocate Dijkstra arrays
        pi = new int[n_];
        kk = new int[n_];
        bb = new int[n_];
        pq = new int[n_ + 1];
        iq = new int[n_];

        int sink = 0 * t + t - 1; // = t-1
        int result = edmonds_karp(n_ - 1, sink);
        System.out.println(result);
        sc.close();
    }
}
